CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "274893c2-7895-4fb2-8644-16e05d91c71c",
  "snapshot_timestamp": "2026-05-21T18:18:16Z",
  "ticket_id": "16f8-4b57",
  "items": [
    {
      "original_text": "When an implementation sub-agent begins work on a task ticket, it posts a WORKTREE_TRACKING:start comment recording its branch name and the orchestrator's session branch before any implementation begins.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior (the sub-agent posting tracking comments at task start) that persists as ongoing functionality after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When sprint or fix-bug begins a session on an epic or bug ticket, it posts a WORKTREE_TRACKING:start comment recording the session branch before dispatching sub-agents.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior that persists after implementation rather than a one-time completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When work completes via harvest-worktree.sh (on any exit path \u2014 success or failure), a WORKTREE_TRACKING:complete comment is written with the branch name and outcome (merged or discarded). If harvest exits abnormally before writing the complete comment, the start comment remains unmatched and resume logic applies on next invocation.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system behavior where the tracking comment is written upon completion, establishing an ongoing property of how the system handles worktree state management"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When resuming a ticket with an unmatched WORKTREE_TRACKING:start comment (no corresponding complete), the orchestrator autonomously assesses the abandoned branch: merges it into the current session branch if it contains at least one commit not reachable from the session branch HEAD and the merge produces no conflicts; discards it if already merged (no unique commits) or if any merge conflict requires manual resolution.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable behavioral capability of the orchestrator system for handling abandoned branches, phrased as ongoing autonomous behavior"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When two competing unmerged implementations exist on a ticket, the orchestrator selects the better one using this priority order: (1) whichever implementation's diff addresses more acceptance criteria items \u2014 where acceptance criteria are markdown task-list items (- [ ] or - [x]) in the ticket description and a criterion is considered addressed when its verbatim text appears in the branch's diff; (2) test-gate-status artifact as tiebreaker when criteria counts are equal; (3) fewest merge conflicts as the final tiebreaker; (4) most recently started by WORKTREE_TRACKING:start comment timestamp as the ultimate fallback.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior (how the orchestrator selects implementations) that persists after implementation, phrased as ongoing operational logic"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When a WORKTREE_TRACKING:start references a branch that no longer exists, the orchestrator skips it without error and proceeds.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes durable system behavior of how the orchestrator handles a specific condition"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "An integration test fixture stages an interrupted-session state (a task ticket with an unmatched WORKTREE_TRACKING:start comment pointing to a branch with unmerged commits) and verifies that resuming the ticket results in an autonomous merge or discard decision without any manual git commands.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability (handling interrupted sessions autonomously) that the test fixture verifies will persist after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "After a story's or bug's changes are merged to main, a WORKTREE_TRACKING:landed comment is written on that ticket confirming the merge completed. For tasks, WORKTREE_TRACKING:complete outcome=merged serves as the equivalent landed signal when the task worktree merges into the session worktree.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system behavior where merged work is tracked and signaled via comments/outcomes, an ongoing property of how the system handles merge confirmations"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When resuming, the orchestrator scans for WORKTREE_TRACKING:start comments on both the top-level epic/bug ticket AND all child story and task tickets. Any ticket \u2014 open or closed \u2014 that has a start but lacks a corresponding complete (tasks) or landed (stories/bugs) is identified as having potentially unmerged changes and evaluated for recovery.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior for how the orchestrator handles resume operations and tracking comments, phrased as ongoing capability"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When ticket comment writes fail (e.g., .tickets-tracker/ unavailable), WORKTREE_TRACKING writes fail silently without blocking sub-agent work; resume skips tracking-based assessment and falls back to checkpoint-only behavior.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system behavior where failures gracefully degrade to fallback behavior, phrased as ongoing property of how the system handles unavailability"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When resuming a ticket with no WORKTREE_TRACKING:start comment, the orchestrator proceeds with existing checkpoint-only resume behavior unchanged.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior that persists after implementation\u2014how the orchestrator handles a specific condition"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    }
  ]
}
